ating to the protection of Confidential Information disclosed hereunder and supersedes all prior and collateral communications, representations and understandings between the Parties hereto relating to the exchange of Confidential Information.","v1451":{"end":7749,"field":"source_text","id":62,"public_sentence_id":62,"start":7415,"text":{"__lsg_shared_value__":"v1452"}},"v1453":{"end":7769,"field":"source_text","id":63,"public_sentence_id":63,"start":7750,"text":"9.5 Governing Law."},"v1455":"This Confidentiality Agreement shall be governed by, and construed in accordance with, the substantive laws of the Republic of Austria.","v1454":{"end":7904,"field":"source_text","id":64,"public_sentence_id":64,"start":7769,"text":{"__lsg_shared_value__":"v1455"}},"v1456":{"end":7931,"field":"source_text","id":66,"public_sentence_id":66,"start":7905,"text":"9.6 Signatures and Dates."},"v1458":"This Confidentiality Agreement is executed by email and treated as original for all legal purposes.","v1457":{"end":8030,"field":"source_text","id":67,"public_sentence_id":67,"start":7931,"text":{"__lsg_shared_value__":"v1458"}},"v1459":{"end":8115,"field":"source_text","id":68,"public_sentence_id":68,"start":8031,"text":"IN WITNESS WHEREOF, the Parties hereto have executed this Confidentiality Agreement."},"v1460":{"end":8137,"field":"source_text","id":69,"public_sentence_id":69,"start":8116,"text":"Signed by: Signed by:"},"v1462":"____________________________________ ____________________________________ . . . . . . . . . . . . . . . . . . . , . . . . . . . . . . . . . . . . . . . .","v1461":{"end":8292,"field":"source_text","id":70,"public_sentence_id":70,"start":8138,"text":{"__lsg_shared_value__":"v1462"}},"v1464":"Chief, Procurement and Contracting Unit (for the Recipient) (for the OSCE) Date___________________________ Date___________________________","v1463":{"end":8430,"field":"source_text","id":74,"public_sentence_id":74,"start":8292,"text":{"__lsg_shared_value__":"v1464"}},"v1380