","def sf_any(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False","

","def sf_normalize(value):
    if not isinstance(value,str):
        value=str(value)
    text=value.casefold().strip()
    text=text.replace('ofthis','of this')
    text=text.replace('relation- ship','relationship')
    text=text.replace('non-d isclosure','non-disclosure')
    text=text.replace('par-ty','party')
    return text","

","def sf_actor(text):
    if 'volunteer' in text:
        return ['named_recipient','Volunteer']
    if 'auditor' in text and 'receiving party' not in text:
        return ['named_recipient','Auditor']
    return ['receiving_party']","

","def sf_information(text):
    items=[['confidential_information']]
    if sf_any(text,['copy','copies','reproduction','record','backup','archive']):
        items.append(['copies_of',['confidential_information']])
    if sf_any(text,['note','abstract','extract','analysis','study','summary','derivative']):
        items.append(['derivative_materials_of',['confidential_information']])
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['information_bundle',items[i],value]
        i-=1
    return value","

","def sf_triggers(text):
    values=[]
    if sf_any(text,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship']):
        values.append(['relationship_nonformation_deadline'])
    if sf_any(text,['termination of service','service terminates','termination of the volunteer service']):
        values.append(['service_termination'])
    if sf_any(text,['termination/expiration of the business relationship','termination or expiration of the business relationship','termination of the business relationship','termination of the working relationship']):
        values.append(['relationship_termination'])
    if sf_any(text,['termination of this agreement','expiration of this agreement','expiration or termination of this agreement','termination/expiration of this agreement','termination of the agreement']):
        values.append(['agreement_termination'])
    if 'completion of the purpose' in text:
        values.append(['purpose_completion'])
    if sf_any(text,['upon request','at any time upon request','promptly upon request','request of','request by','request from']):
        values.append(['request_by',['disclosing_party']])
    return sf_unique(values)","

","def sf_trigger_value(values):
    if not values:
        return None
    value=values[0]
    i=1
    while i<len(values):
        value=['trigger_alternative',value,values[i]]
        i+=1
    return value","

","def sf_parse_disposal(raw,uid,out):
    text=sf_normalize(raw)
    triggers=sf_triggers(text)
    if not triggers:
        return
    returned=sf_any(text,['shall return','return to','returned to','promptly return','information will be returned'])
    destroyed=sf_any(text,['shall be destroyed','or destroy','destroy it','certify the destruction','ensure the destruction','promptly destroy']) and 'not destroyed' not in text
    if not returned and not destroyed:
        return
    information=sf_information(text)
    if returned and destroyed:
        action=['action_alternative',['return_to',information,['disclosing_party']],['destroy',information]]
    elif returned:
        action=['return_to',information,['disclosing_party']]
    else:
        action=['destroy',information]
    sf_add(out,['disposal_obligation',sf_actor(text),action,sf_trigger_value(triggers),['no_exceptions']],[uid])","

","def sf_parse_retention(raw,uid,out):
    text=sf_normalize(raw)
    information=sf_information(text)
    actor=sf_actor(text)
    if sf_any(text,['entitled to retain','may retain','permitted to retain','may maintain a single copy']):
        sf_add(out,['retention_permission',actor,information,['after_disposal'],['retention_condition',raw]],[uid])
    if sf_any(text,['without retaining any copies','without retaining any copy','no copies or records thereof shall be retained','no copy shall be retained','no copies, electronic or otherwise, notes or abstracts of the foregoing shall be retained']):
        sf_add(out,['retention_prohibition',actor,information,['after_disposal']],[uid])
