","def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=acq_entries(premises)
    if task in ('nda-5','nda-7'):
        return acq_disclosure(task,entries)
    disposal=[]
    retention_permissions=[]
    retention_prohibitions=[]
    absolute_prohibitions=[]
    no_disposal=[]
    no_retention=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0]=='retention_prohibition':
            retention_prohibitions.append(root)
        elif term[0]=='absolute_retention_prohibition':
            absolute_prohibitions.append(root)
        elif term[0]=='complete_source_no_disposal_obligation':
            no_disposal.append(root)
        elif term[0]=='complete_source_no_retention_effect':
            no_retention.append(root)
    if task=='nda-16':
        endpoint=[]
        relevant=[]
        for term,root in disposal:
            action=term[2]
            trigger=term[3]
            if not (acq_has(action,'return_to') or acq_has(action,'destroy')):
                continue
            relevant.append(root)
            if acq_has(trigger,'agreement_termination') or acq_has(trigger,'service_termination') or acq_has(trigger,'relationship_termination') or acq_has(trigger,'relationship_nonformation_deadline') or acq_has(trigger,'purpose_completion'):
                endpoint.append(root)
        if endpoint:
            return {'handled':True,'answer':'Entailment','used_nodes':acq_unique(endpoint)}
        if relevant or no_disposal:
            return {'handled':True,'answer':'NotMentioned','used_nodes':acq_unique(relevant+no_disposal)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':acq_unique(retention_permissions)}
    if retention_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':acq_unique(retention_prohibitions)}
    if absolute_prohibitions and disposal:
        return {'handled':True,'answer':'Contradiction','used_nodes':acq_unique(absolute_prohibitions+[root for term,root in disposal])}
    relevant=[]
    for term,root in disposal:
        if acq_has(term[2],'return_to') or acq_has(term[2],'destroy'):
            relevant.append(root)
    if relevant or no_retention or no_disposal:
        return {'handled':True,'answer':'NotMentioned','used_nodes':acq_unique(relevant+no_retention+no_disposal)}
    return {'handled':False,'answer':None,'used_nodes':[]}","

