","def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=collect_entries(premises)
    if task in ('nda-5','nda-7'):
        return disclosure_answer(task,entries)
    disposal=[]
    retention_permissions=[]
    retention_prohibitions=[]
    absence=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0] in ('retention_prohibition','absolute_retention_prohibition'):
            retention_prohibitions.append(root)
        elif term[0] in ('complete_source_no_disposal_obligation','complete_source_no_retention_effect','complete_source_rule_absence'):
            absence.append(root)
    if task=='nda-16':
        endpoint=[]
        relevant=[]
        for term,root in disposal:
            action=term[2]
            trigger=term[3]
            if not (has_tag(action,'return_to') or has_tag(action,'destroy')):
                continue
            relevant.append(root)
            if has_tag(trigger,'agreement_termination') or has_tag(trigger,'service_termination') or has_tag(trigger,'relationship_termination') or has_tag(trigger,'relationship_nonformation_deadline') or has_tag(trigger,'purpose_completion'):
                endpoint.append(root)
        if endpoint:
            return {'handled':True,'answer':'Entailment','used_nodes':unique(endpoint)}
        if relevant or absence:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+absence)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':unique(retention_permissions)}
    if retention_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(retention_prohibitions)}
    relevant=[]
    for term,root in disposal:
        if has_tag(term[2],'return_to') or has_tag(term[2],'destroy'):
            relevant.append(root)
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}","

